import React, {useMemo, useContext, type ReactNode} from 'react';
import {ReactContextError} from '@docusaurus/theme-common/internal';
import type {PropSidebar} from '@docusaurus/plugin-content-docs';
import type {
  GlobalPluginData,
  GlobalVersion,
} from '@docusaurus/plugin-content-docs/client';
import {
  DocsDocumentRecord,
  matchDocsRoute,
  matchPath,
  RouteLocation,
} from './docsVersion';

export {matchDocsRoute, matchPath, RouteLocation};

// Using a Symbol because null is a valid context value (a doc with no sidebar)
// Inspired by https://github.com/jamiebuilds/unstated-next/blob/master/src/unstated-next.tsx
const EmptyContext: unique symbol = Symbol('EmptyContext');

type ContextValue = {name: string; items: PropSidebar};

const Context = React.createContext<ContextValue | null | typeof EmptyContext>(
  EmptyContext,
);

/**
 * Provide the current sidebar to your children.
 */
export function DocsSidebarProvider({
  children,
  name,
  items,
}: {
  children: ReactNode;
  name: string | undefined;
  items: PropSidebar | undefined;
}): JSX.Element {
  const stableValue: ContextValue | null = useMemo(
    () => (name && items ? {name, items} : null),
    [name, items],
  );
  return <Context.Provider value={stableValue}>{children}</Context.Provider>;
}

/**
 * Gets the sidebar that's currently displayed, or `null` if there isn't one
 */
export function useDocsSidebar(): ContextValue | null {
  const value = useContext(Context);
  if (value === EmptyContext) {
    throw new ReactContextError('DocsSidebarProvider');
  }
  return value;
}

export class DocsVersionRecord {
  constructor(private readonly version: GlobalVersion) {}

  get name(): string {
    return this.version.name;
  }

  get label(): string {
    return this.version.label;
  }

  get isLast(): boolean {
    return this.version.isLast;
  }

  get path(): string {
    return this.version.path;
  }

  get mainDocId(): string {
    return this.version.mainDocId;
  }

  get docs(): DocsDocumentRecord[] {
    return (this.version.docs ?? []).map((doc) => new DocsDocumentRecord(doc));
  }

  unwrap(): GlobalVersion {
    return this.version;
  }
}

export class DocsPluginRecord {
  constructor(private readonly data: GlobalPluginData) {}

  get path(): string {
    return this.data.path;
  }

  get versions(): DocsVersionRecord[] {
    return this.data.versions.map((version) => new DocsVersionRecord(version));
  }

  get breadcrumbs(): boolean {
    return this.data.breadcrumbs;
  }
}

